package wgmodern;
import java.util.UUID;import com.mojang.authlib.GameProfile;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.material.Fluids;import net.minecraftforge.gametest.*;import net.minecraftforge.common.util.FakePlayerFactory;import net.minecraftforge.fluids.*;import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class UtilityServerTests {
 @GameTest(template="empty") public static void capsuleTransfersWholeBucketsAndPreservesContainer(GameTestHelper h){
  var capsule=new ItemStack(Content.CAPSULE.get());var handler=FluidUtil.getFluidHandler(capsule).orElseThrow(()->new IllegalStateException("Missing fluid capability"));
  h.assertTrue(handler.fill(new FluidStack(Fluids.WATER,999),FluidAction.EXECUTE)==0,"Partial fluid cannot fill a capsule");h.assertTrue(handler.fill(new FluidStack(Fluids.WATER,1500),FluidAction.SIMULATE)==1000&&CrystalCapsule.fluid(capsule).isEmpty(),"Simulation accepts one bucket without mutation");handler.fill(new FluidStack(Fluids.WATER,1500),FluidAction.EXECUTE);h.assertTrue(CrystalCapsule.fluid(capsule).getAmount()==1000,"Full capsule stores precisely one bucket");h.assertTrue(handler.drain(999,FluidAction.EXECUTE).isEmpty()&&handler.drain(new FluidStack(Fluids.LAVA,1000),FluidAction.EXECUTE).isEmpty(),"Partial and wrong-fluid requests rejected");var saved=ItemStack.of(capsule.save(new net.minecraft.nbt.CompoundTag()));h.assertTrue(CrystalCapsule.fluid(saved).getFluid()==Fluids.WATER,"Fluid survives item serialization");h.assertTrue(capsule.getItem().getCraftingRemainingItem(capsule).is(Content.CAPSULE.get()),"Crafting returns the empty capsule");handler.drain(1000,FluidAction.EXECUTE);h.assertTrue(CrystalCapsule.fluid(capsule).isEmpty(),"Whole drain empties container");capsule.setCount(2);h.assertTrue(handler.fill(new FluidStack(Fluids.WATER,1000),FluidAction.EXECUTE)==0,"A capability cannot overwrite multiple stacked capsules");pass(h);
 }
 @GameTest(template="empty") public static void roseMaturesAndOnlyClimbsSupportedWalls(GameTestHelper h){
  var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));var rose=(RoseVines)Content.ROSE.get();l.setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(pos,rose.attachments(l,pos,rose.defaultBlockState()));for(int i=0;i<5;i++)rose.grow(l,pos,l.random,true);h.assertTrue(l.getBlockState(pos).getValue(RoseVines.AGE)==5,"Five growth steps mature the rose");rose.grow(l,pos,l.random,true);h.assertTrue(l.isEmptyBlock(pos.above()),"Ground roses cannot grow into unsupported air");l.setBlockAndUpdate(pos.above().north(),Blocks.STONE.defaultBlockState());rose.grow(l,pos,l.random,true);h.assertTrue(l.getBlockState(pos.above()).is(rose)&&l.getBlockState(pos.above()).getValue(RoseVines.FACES.get(Direction.NORTH)),"Mature rose climbs an adjacent solid wall");h.assertTrue(l.isEmptyBlock(pos.east())&&rose.onSheared(null,new ItemStack(Items.SHEARS),l,pos,0).get(0).is(Content.ROSE_ITEM.get()),"No horizontal spread and shearing returns one vine");h.assertTrue(l.getBlockState(pos).getCollisionShape(l,pos).isEmpty(),"Vines do not block movement");pass(h);
 }
 @GameTest(template="empty") public static void labelLibraryValidatesKnowledgeAndConsumesLabels(GameTestHelper h){
  var l=h.getLevel();var pos=h.absolutePos(new BlockPos(1,2,1));l.setBlockAndUpdate(pos,Content.LABEL.get().defaultBlockState());var tile=(LabelLibrary.Tile)l.getBlockEntity(pos);var player=FakePlayerFactory.get(l,new GameProfile(UUID.fromString("e747cc43-10ca-4743-abfc-2fd7b71598bf"),"LabelTester"));player.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);var knowledge=tc4revival.research.KnowledgeSavedData.get(l.getServer());knowledge.ensure(player.getUUID(),n->0);var menu=new LabelMenu(1,player.getInventory(),pos);var catalog=tc4revival.aspect.TCAspects.catalog();var air=catalog.require("aer");h.assertTrue(menu.clickMenuButton(player,catalog.all().indexOf(air)),"Known primal is selectable");h.assertTrue(!menu.clickMenuButton(player,-1)&&!menu.clickMenuButton(player,Integer.MAX_VALUE),"Forged aspect indices rejected");tile.setItem(0,new ItemStack(tc4revival.content.TCItems.JAR_LABEL.get(),3));var output=tile.getItem(1);h.assertTrue(!output.isEmpty()&&((tc4revival.content.StoredAspectItem)output.getItem()).storedAspects(output).contains(air),"Known aspect marks output label");var data=tile.saveWithFullMetadata();h.assertTrue(data.getList("Items",10).size()==1,"Virtual output is not saved or duplicated");menu.slots.get(1).onTake(player,output);h.assertTrue(tile.getItem(0).getCount()==2,"Taking one output consumes exactly one label");tile.load(data);h.assertTrue(tile.getItem(0).getCount()==3&&tile.aspect.equals("aer")&&!tile.getItem(1).isEmpty(),"Input and selected aspect survive reload");h.assertTrue(menu.quickMoveStack(player,1).isEmpty(),"Legacy label library disables shift transfer");player.setPos(pos.getX()+100,pos.getY(),pos.getZ());h.assertTrue(!menu.clickMenuButton(player,catalog.all().indexOf(air)),"Remote menu operations rejected");pass(h);
 }
 @GameTest(template="empty") public static void mirrorPumpDrainsLinkedSourceAndRejectsInvalidExtractions(GameTestHelper h){
  var l=h.getLevel();var p=h.absolutePos(new BlockPos(2,3,2));l.setBlockAndUpdate(p,Content.PUMP.get().defaultBlockState());var pump=(MirrorPump.Tile)l.getBlockEntity(p);var air=tc4revival.aspect.TCAspects.catalog().require("aer");l.setBlockAndUpdate(p.north(),tc4revival.content.TCArcane.ESSENTIA_JAR.get().defaultBlockState());var filterJar=new ItemStack(tc4revival.content.TCItems.ESSENTIA_JAR.get());filterJar.getOrCreateTag().putString("AspectFilter","aer");((tc4revival.content.EssentiaJarBlockEntity)l.getBlockEntity(p.north())).readItem(filterJar);
  var near=p.south(2);var remote=p.east(5).south(2);l.setBlockAndUpdate(near.south(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(near,tc4revival.content.TCArcane.ESSENTIA_MIRROR.get().defaultBlockState().setValue(tc4revival.content.EssentiaMirrorBlock.FACING,Direction.NORTH));l.setBlockAndUpdate(remote.east(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(remote,tc4revival.content.TCArcane.ESSENTIA_MIRROR.get().defaultBlockState().setValue(tc4revival.content.EssentiaMirrorBlock.FACING,Direction.WEST));var a=(tc4revival.content.EssentiaMirrorBlockEntity)l.getBlockEntity(near);var b=(tc4revival.content.EssentiaMirrorBlockEntity)l.getBlockEntity(remote);a.remember(GlobalPos.of(l.dimension(),remote));h.assertTrue(a.restoreLink(),"Mirrors establish reciprocal link");var jarPos=remote.west(2);l.setBlockAndUpdate(jarPos,tc4revival.content.TCArcane.ESSENTIA_JAR.get().defaultBlockState());var jar=(tc4revival.content.EssentiaJarBlockEntity)l.getBlockEntity(jarPos);jar.addToContainer(air,5);
  h.assertTrue(pump.mirrors().contains(a),"Pump sees rear mirror within original search prism");MirrorPump.Tile.tick(l,p,pump.getBlockState(),pump);h.assertTrue(pump.amount==1&&air.equals(pump.aspect)&&jar.contains(air,4)&&!jar.contains(air,5),"Pump imports one requested essentia through paired mirror");h.assertTrue(pump.takeEssentia(air,-1,Direction.NORTH)==0&&pump.takeEssentia(air,1,Direction.SOUTH)==0&&pump.takeEssentia(tc4revival.aspect.TCAspects.catalog().require("ignis"),1,Direction.NORTH)==0,"Negative, wrong-side and wrong-aspect extractions cannot duplicate or corrupt stored essentia");var saved=pump.saveWithFullMetadata();pump.load(saved);h.assertTrue(pump.takeEssentia(air,1,Direction.NORTH)==1&&pump.amount==0&&pump.aspect==null,"Persisted unit transfers once through facing outlet");pass(h);
 }
 @GameTest(template="empty") public static void kamaConversionPreservesCloakStorageAndEnchantment(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("79b21586-5559-4419-b642-a4247b16b9ba"),"KamaTester"));var grid=new net.minecraft.world.inventory.TransientCraftingContainer(p.inventoryMenu,3,3);var cloak=new ItemStack(Content.CLOAKS.get("cloak_storage").get());var list=NonNullList.withSize(27,ItemStack.EMPTY);list.set(26,new ItemStack(Items.DIAMOND,23));CloakItem.store(cloak,list);cloak.enchant(WGMagic.ENCHANTS.get("invisible_gear").get(),1);((CloakItem)cloak.getItem()).setColor(cloak,0x448877);grid.setItem(0,new ItemStack(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new net.minecraft.resources.ResourceLocation("thaumcraft","mundane_belt"))));grid.setItem(3,cloak);var recipe=(tc4revival.content.ArcaneRecipe)h.getLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation("witchinggadgets","kama_storage")).orElseThrow();h.assertTrue(recipe.matches(grid,h.getLevel()),"Original belt-over-cloak recipe matches");var result=recipe.assemble(grid,h.getLevel().registryAccess());h.assertTrue(result.is(Content.CLOAKS.get("kama_storage").get())&&CloakItem.contents(result).get(26).getCount()==23,"Kama conversion retains all stored contents");h.assertTrue(result.getTag().getCompound("display").getInt("color")==0x448877&&net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("invisible_gear").get(),result)==1,"Color and enchantments survive conversion");result.getTag().putString("Mutation","private");h.assertTrue(!cloak.getTag().contains("Mutation"),"Output does not alias ingredient NBT");pass(h);}
 @GameTest(template="empty") public static void calculatorReducesNodesAndReportsAsymmetricPedestals(GameTestHelper h){var catalog=tc4revival.aspect.TCAspects.catalog();var reduced=ArcaneCalculator.primals(new tc4revival.aspect.AspectAmounts().add(catalog.require("motus"),10));h.assertTrue(reduced.amount(catalog.require("aer"))==10&&reduced.amount(catalog.require("ordo"))==10&&reduced.total()==20,"Calculator expands compound quantities into both primal parents");var l=h.getLevel();var origin=h.absolutePos(new BlockPos(3,5,3));var pedestal=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getValue(new net.minecraft.resources.ResourceLocation("thaumcraft","arcane_pedestal"));var east=origin.east(2).below();var west=origin.west(2).below();l.setBlockAndUpdate(east,pedestal.defaultBlockState());l.setBlockAndUpdate(west,pedestal.defaultBlockState());((tc4revival.content.ArcanePedestalBlockEntity)l.getBlockEntity(east)).setItem(0,new ItemStack(Items.DIAMOND));var bad=origin.east(4);l.setBlockAndUpdate(bad,pedestal.defaultBlockState());var report=ArcaneCalculator.survey(l,origin);h.assertTrue(report.symmetry()==1&&report.pedestals().size()==2,"One unmatched item increases instability by one");h.assertTrue(report.warnings().stream().anyMatch(w->w.kind().equals("pedestalHeight")&&w.pos().equals(bad))&&report.warnings().stream().anyMatch(w->w.kind().equals("noPartnerItem")),"Invalid heights and unmatched items produce coordinate warnings");((tc4revival.content.ArcanePedestalBlockEntity)l.getBlockEntity(west)).setItem(0,new ItemStack(Items.STICK));h.assertTrue(ArcaneCalculator.survey(l,origin).symmetry()==0,"Counterpart occupancy restores symmetry independent of item identity");pass(h);}
 @GameTest(template="empty") public static void guidingStringRecordsTurnsAndClearsOnlyOnSneakUse(GameTestHelper h){var l=h.getLevel();var p=FakePlayerFactory.get(l,new GameProfile(UUID.fromString("f6958c4a-5d41-4fb2-9766-de90f06b1a1b"),"StringTester"));var s=new ItemStack(Content.GUIDING_STRING.get());p.setPos(1,30,1);p.setYRot(0);p.setShiftKeyDown(false);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,s);s.getItem().use(l,p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(LabyrinthString.active(s)&&LabyrinthString.points(s).size()==1,"Activation stores initial point");p.setPos(5,30,1);s.getItem().inventoryTick(s,l,p,0,true);h.assertTrue(LabyrinthString.points(s).size()==1,"Straight movement does not add points every tick");p.setYRot(90);s.getItem().inventoryTick(s,l,p,0,true);h.assertTrue(LabyrinthString.points(s).size()==2,"A turn after movement records a waypoint");var copy=ItemStack.of(s.save(new net.minecraft.nbt.CompoundTag()));h.assertTrue(LabyrinthString.points(copy).getCompound(1).getDouble("x")==5,"Path persists in item NBT");s.getItem().use(l,p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(!LabyrinthString.active(s)&&LabyrinthString.points(s).size()==3,"Stopping preserves path and final point");p.setShiftKeyDown(true);s.getItem().use(l,p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(!LabyrinthString.active(s)&&LabyrinthString.points(s).isEmpty(),"Sneak activation clears path");pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
